// Português (Brasil) UI catalog — partial by design (owner 2026-10-13: periodic translation; normal
// development maintains only zh-CN + en). Missing keys fall back to en at lookup time
// (i18n/index.tsx); `...modulesEn` first keeps every key present, the entries below override.
//
// Glossário (mantido pela tradução de 2026-10-15; siga-o ao acrescentar chaves):
//   Profile = perfil · turn = turno · runtime = runtime (masc.) · queue = fila · steer = direcionar /
//   inserir · side chat = conversa paralela · bus = barramento · bookmark = favorito · note = nota ·
//   quota = cota · usage limit = limite de uso · release = versão · rollback = reverter / reversão ·
//   one-way update = atualização de mão única · preflight = preflight · quick launch = Início rápido ·
//   workflow = fluxo de trabalho · run (workflow) = execução · step = etapa · batch = lote ·
//   idle = ocioso · deployed by hand = implantado à mão · backend / host / branch / build / endpoint /
//   Base URL / login / token / job = mantidos · canais de atualização: Lançamento / Desenvolvimento
//   (Dev) · Full access = Acesso total · "price as another model" = "Precificar como outro modelo" ·
//   price table = tabela de preços · scan = varredura
