  "workSurface.widthRules": "Inteligente (padrão): um espaço de trabalho pelo conteúdo, dois preenchem a janela, com as conversas dividindo a largura na proporção que você arrastou por último. Pelo conteúdo: a coluna da conversa e seu {{shelf}} mantêm cada um sua largura, centralizados juntos, com a área de trabalho dos dois lados. Preencher a janela: as colunas dividem a largura da janela inteira. Isso define só as larguras; os cartões mantêm cantos, espaços e sombras (De borda a borda é uma configuração própria abaixo). Arrastar a borda entre dois painéis muda só esses dois; clique duplo para os padrões deles; mover o foco nunca muda o layout",
